import { CommonModule } from '@angular/common';
import { Component, Input, OnChanges } from '@angular/core';

import { CodeIdentifier, CodeSegment, LegendChip, legendChips, segmentLine } from './code-block-segments';

/** One rendered C source line with its autogenerated datasheet comment (ucd-iso: cmod's `/code` door). */
export interface CodeBlockLine {
  n: number;
  text: string;
  comment?: string;
}

/**
 * code-block — a reusable monospace code panel (ucd-iso-1, his ruling 2026-10-10: "a code-interface that shows it
 * as though it is actual c-code … with comment that should autogenerate saying which data-sheet they should come
 * from"). No syntax-highlighting library — theme tokens only, newlines preserved, one "copy" control.
 *
 * Two shapes of input, either one:
 *   - `text`: a plain multi-line string (a CIsotope's `source`, or any `col:code` table cell).
 *   - `lines`: numbered lines with a per-line autogenerated `comment`, shown right-aligned and muted on that
 *     line (the CFunctionAtom code-interface's `lines[]`, preferred there over the flat `rendered` string so the
 *     comment can be styled apart from the code).
 * `lines` wins when both are given.
 */
@Component({
  standalone: true,
  selector: 'code-block',
  imports: [CommonModule],
  template: `
    <div class="code-block">
      <div class="code-block-bar">
        <button type="button" class="copy" (click)="copy()">{{ copied ? 'copied' : 'copy' }}</button>
      </div>
      <div class="kind-legend" *ngIf="legend.length && showLegend !== false">
        <span class="chip" *ngFor="let c of legend" [ngClass]="'kind-' + c.kind">{{ c.label }} {{ c.count }}</span>
      </div>
      <pre *ngIf="lines && lines.length; else plainBlock"><div class="line" *ngFor="let l of lines"><span class="n">{{ l.n }}</span><span class="t" *ngIf="!legend.length">{{ l.text }}</span><span class="t" *ngIf="legend.length"><ng-container *ngFor="let s of segs(l.text)"><span *ngIf="s.kind" class="ident" [ngClass]="'kind-' + s.kind" [title]="s.why || ''">{{ s.text }}</span><ng-container *ngIf="!s.kind">{{ s.text }}</ng-container></ng-container></span><span class="c" *ngIf="l.comment">{{ l.comment }}</span></div></pre>
      <ng-template #plainBlock><pre class="plain">{{ text }}</pre></ng-template>
    </div>
  `,
  styles: [`
    .code-block { position: relative; border-radius: 8px; background: var(--surface-alt, #f4f4f4); }
    .code-block-bar { display: flex; justify-content: flex-end; padding: 4px 6px 0; }
    button.copy {
      padding: 2px 10px; border: 1px solid var(--border-medium, #ddd); border-radius: 10px;
      background: var(--surface-variant, #eee); color: var(--text-secondary, #666);
      font: inherit; font-size: .78em; cursor: pointer;
    }
    button.copy:hover { background: var(--surface-hover, #e4e4e4); }
    pre {
      margin: 0; padding: 4px 12px 10px; overflow-x: auto; font-family: var(--font-mono, monospace);
      font-size: .88em; line-height: 1.5; white-space: pre;
    }
    pre.plain { white-space: pre-wrap; }
    .line { display: flex; gap: 10px; white-space: pre; }
    .line .n { flex: 0 0 auto; min-width: 2.2em; text-align: right; color: var(--text-tertiary, #999); user-select: none; }
    .line .t { flex: 0 1 auto; white-space: pre; }
    .kind-legend { display: flex; flex-wrap: wrap; gap: 6px; padding: 2px 12px 4px; font-size: .78em; }
    .kind-legend .chip { padding: 1px 8px; border-radius: 10px; }
    .ident { border-radius: 3px; padding: 0 2px; }
    .kind-pin-macro { background: var(--code-kind-pin-macro); color: var(--code-kind-pin-macro-text); }
    .kind-register { background: var(--code-kind-register); color: var(--code-kind-register-text); }
    .kind-knob { background: var(--code-kind-knob); color: var(--code-kind-knob-text); }
    .kind-global { background: var(--code-kind-global); color: var(--code-kind-global-text); }
    .kind-library { background: var(--code-kind-library); color: var(--code-kind-library-text); }
    .line .c { flex: 1 1 auto; text-align: right; color: var(--text-secondary, #666); font-style: italic; white-space: nowrap; padding-left: 16px; }
  `],
})
export class CodeBlockComponent implements OnChanges {
  @Input() text = '';
  @Input() lines: CodeBlockLine[] | null = null;

  /** aut-1: identifiers the `/code` door returned — coloured by kind inside each line (none = unchanged). */
  @Input() identifiers: CodeIdentifier[] = [];
  /** Legend row above the block; defaults to on whenever identifiers are present. */
  @Input() showLegend = true;

  copied = false;
  legend: LegendChip[] = [];
  private cache = new Map<string, CodeSegment[]>();

  ngOnChanges(): void {
    this.legend = legendChips(this.identifiers);
    this.cache.clear();
  }

  segs(text: string): CodeSegment[] {
    let r = this.cache.get(text);
    if (!r) { r = segmentLine(text, this.identifiers); this.cache.set(text, r); }
    return r;
  }

  copy(): void {
    const payload = this.lines && this.lines.length ? this.lines.map((l) => l.text).join('\n') : this.text;
    const done = () => { this.copied = true; setTimeout(() => { this.copied = false; }, 1200); };
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(payload || '').then(done).catch(() => { /* clipboard denied — the text is still selectable */ });
    }
  }
}
